const $=id=>document.getElementById(id),params=new URLSearchParams(location.hash.slice(1)),room=params.get('room'),key=params.get('key');let cue,stream,expiry;
function render(next){if(next.schema!=='btr.broadcast-cue.v1'||next.source!=='upload'||(cue&&next.sequence<=cue.sequence))return;cue=next;$('connection').textContent='SYNCED';$('clock').textContent=cue.clock;$('revision').textContent='REVISION '+cue.revision;$('title').textContent=cue.title;$('body').textContent=cue.body;$('source').textContent=cue.source_id;$('event').textContent=cue.evidence_ids.join(', ')||'No observation yet';$('decision').textContent=cue.explanation.decision==='withdraw'?'WITHDRAWN · NO CLAIM RELEASED':cue.evidence_ids.length?'REPORTED OBSERVATION · QUALIFIED':'AWAITING EVIDENCE';$('cue').dataset.withdrawn=String(cue.experience.corrected);$('limit').textContent=cue.explanation.review;const metrics=$('metrics');metrics.replaceChildren();const m=cue.explanation.calculation;if(m)for(const[k,label]of [['distance_m','m'],['speed_kmh','km/h']])if(Number.isFinite(m[k])){const span=document.createElement('span');span.textContent=m[k].toFixed(1)+' '+label;metrics.append(span);}metrics.hidden=!metrics.childElementCount;$('hear').disabled=false;clearTimeout(expiry);expiry=setTimeout(()=>$('connection').textContent='LAST RECEIVED · RECONNECTING',Math.max(0,cue.expires_at-Date.now()));}
$('hear').onclick=()=>{if(!cue||!('speechSynthesis'in window))return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(cue.title+'. '+cue.body);utterance.lang='en-US';speechSynthesis.speak(utterance);};
let stopped=false;const controller=new AbortController();
async function connect(base){while(!stopped){try{const response=await fetch(base+'/api/broadcast/'+room+'/stream',{headers:{Authorization:'Bearer '+key},signal:controller.signal});if(!response.ok){if([403,410].includes(response.status)){stopped=true;$('connection').textContent='SESSION ENDED';return;}throw Error('Unavailable');}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(!stopped){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});if(buffer.length>256000)throw Error('Oversized stream');let at;while((at=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,at);buffer=buffer.slice(at+2);const type=block.split('\n').find(line=>line.startsWith('event:'))?.slice(6).trim(),raw=block.split('\n').filter(line=>line.startsWith('data:')).map(line=>line.slice(5)).join('');if(type==='cue'&&raw)render(JSON.parse(raw));if(type==='stopped'){stopped=true;clearTimeout(expiry);$('connection').textContent='SESSION ENDED';await reader.cancel();}}}}catch{if(!stopped)$('connection').textContent='RECONNECTING';}if(!stopped)await new Promise(resolve=>setTimeout(resolve,1800));}}
if(!/^[a-f0-9]{24}$/.test(room||'')||!/^[a-f0-9]{48}$/.test(key||'')){$('connection').textContent='PAIR FROM DESKTOP';}else fetch('api-config.json').then(r=>r.json()).then(config=>connect(config.baseUrl||'')).catch(()=>$('connection').textContent='CONNECTION UNAVAILABLE');
addEventListener('pagehide',()=>{stopped=true;controller.abort();clearTimeout(expiry);});
